    const args = { _: ['build'], targets: targetMode, clean: false, watch: false }

    const origSetPluginsToSkip = service.setPluginsToSkip.bind(service)
    service.setPluginsToSkip = function (a) {
      origSetPluginsToSkip(a, rawArgv)
